            "diff": "diff --git a/test/req.fresh.js b/test/req.fresh.js\n--- a/test/req.fresh.js\n+++ b/test/req.fresh.js\n@@ -2,6 +2,7 @@\n \n var express = require('../')\n   , request = require('supertest');\n+var shouldSkipQuery = require('./support/utils').shouldSkipQuery\n \n describe('req', function(){\n   describe('.fresh', function(){\n@@ -46,5 +47,42 @@ describe('req', function(){\n       .get('/')\n       .expect(200, 'false', done);\n     })\n+\n+    it('should return true for a QUERY request with a body when the resource is not modified', function(done){\n+      if (shouldSkipQuery(process.versions.node)) {\n+        this.skip()\n+      }\n+      var app = express();\n+      var etag = '\"12345\"';\n+\n+      app.use(function(req, res){\n+        res.set('ETag', etag);\n+        res.send(req.fresh);\n+      });\n+\n+      request(app)\n+      .query('/')\n+      .set('If-None-Match', etag)\n+      .send({ ids: ['a', 'b'] })\n+      .expect(304, done);\n+    })\n+\n+    it('should return false for a QUERY request with a body when the resource is modified', function(done){\n+      if (shouldSkipQuery(process.versions.node)) {\n+        this.skip()\n+      }\n+      var app = express();\n+\n+      app.use(function(req, res){\n+        res.set('ETag', '\"123\"');\n+        res.send(req.fresh);\n+      });\n+\n+      request(app)\n+      .query('/')\n+      .set('If-None-Match', '\"12345\"')\n+      .send({ ids: ['a', 'b'] })\n+      .expect(200, 'false', done);\n+    })\n   })\n })",
            "fullContent": "'use strict'\n\nvar express = require('../')\n  , request = require('supertest');\nvar shouldSkipQuery = require('./support/utils').shouldSkipQuery\n\ndescribe('req', function(){\n  describe('.fresh', function(){\n    it('should return true when the resource is not modified', function(done){\n      var app = express();\n      var etag = '\"12345\"';\n\n      app.use(function(req, res){\n        res.set('ETag', etag);\n        res.send(req.fresh);\n      });\n\n      request(app)\n      .get('/')\n      .set('If-None-Match', etag)\n      .expect(304, done);\n    })\n\n    it('should return false when the resource is modified', function(done){\n      var app = express();\n\n      app.use(function(req, res){\n        res.set('ETag', '\"123\"');\n        res.send(req.fresh);\n      });\n\n      request(app)\n      .get('/')\n      .set('If-None-Match', '\"12345\"')\n      .expect(200, 'false', done);\n    })\n\n    it('should return false without response headers', function(done){\n      var app = express();\n\n      app.disable('x-powered-by')\n      app.use(function(req, res){\n        res.send(req.fresh);\n      });\n\n      request(app)\n      .get('/')\n      .expect(200, 'false', done);\n    })\n\n    it('should return true for a QUERY request with a body when the resource is not modified', function(done){\n      if (shouldSkipQuery(process.versions.node)) {\n        this.skip()\n      }\n      var app = express();\n      var etag = '\"12345\"';\n\n      app.use(function(req, res){\n        res.set('ETag', etag);\n        res.send(req.fresh);\n      });\n\n      request(app)\n      .query('/')\n      .set('If-None-Match', etag)\n      .send({ ids: ['a', 'b'] })\n      .expect(304, done);\n    })\n\n    it('should return false for a QUERY request with a body when the resource is modified', function(done){\n      if (shouldSkipQuery(process.versions.node)) {\n        this.skip()\n      }\n      var app = express();\n\n      app.use(function(req, res){\n        res.set('ETag', '\"123\"');\n        res.send(req.fresh);\n      });\n\n      request(app)\n      .query('/')\n      .set('If-None-Match', '\"12345\"')\n      .send({ ids: ['a', 'b'] })\n      .expect(200, 'false', done);\n    })\n  })\n})\n",
