      "diff": "diff --git a/lib/request.js b/lib/request.js\n--- a/lib/request.js\n+++ b/lib/request.js\n@@ -253,19 +253,13 @@ Object.defineProperties(Request.prototype, {\n   },\n   port: {\n     get () {\n-      // first try taking port from host\n-      const portFromHost = parseInt(this.host.split(':').slice(-1)[0])\n-      if (!isNaN(portFromHost)) {\n-        return portFromHost\n+      const portReg = /(?<port>:\\d+)$/\n+      const host = this.headers.host ?? this.headers[':authority'] ?? ''\n+      const matches = portReg.exec(host)\n+      if (matches === null || matches[1] === undefined) {\n+        return null\n       }\n-      // now fall back to port from host/:authority header\n-      const host = (this.headers.host ?? this.headers[':authority'] ?? '')\n-      const portFromHeader = parseInt(host.split(':').slice(-1)[0])\n-      if (!isNaN(portFromHeader)) {\n-        return portFromHeader\n-      }\n-      // fall back to null\n-      return null\n+      return parseInt(matches.groups.port.slice(1), 10)\n     }\n   },\n   protocol: {\n\ndiff --git a/test/request-port.test.js b/test/request-port.test.js\n--- /dev/null\n+++ b/test/request-port.test.js\n@@ -0,0 +1,72 @@\n+'use strict'\n+\n+const test = require('node:test')\n+const Request = require('../lib/request')\n+\n+test('.port parses port correctly', (t) => {\n+  const fixtures = [\n+    {\n+      expected: 80,\n+      req: {\n+        headers: {\n+          host: 'example.com:80'\n+        }\n+      }\n+    },\n+    {\n+      expected: 443,\n+      req: {\n+        headers: {\n+          host: 'example.com:443'\n+        }\n+      }\n+    },\n+    {\n+      expected: 80,\n+      req: {\n+        headers: {\n+          host: '[::1]:80'\n+        }\n+      }\n+    },\n+    {\n+      expected: 443,\n+      req: {\n+        headers: {\n+          host: '[::1]:443'\n+        }\n+      }\n+    },\n+    {\n+      expected: null,\n+      req: {\n+        headers: {\n+          host: '[::1]'\n+        }\n+      }\n+    },\n+    {\n+      expected: 80,\n+      req: {\n+        headers: {\n+          ':authority': '1.2.3.4:80'\n+        }\n+      }\n+    },\n+    {\n+      expected: null,\n+      req: {\n+        headers: {}\n+      }\n+    }\n+  ]\n+\n+  for (const fixture of fixtures) {\n+    const req = new Request(1, {}, fixture.req, '', {}, {})\n+    t.assert.equal(\n+      req.port,\n+      fixture.expected,\n+      `${fixture.req.headers.host} should parse to ${fixture.expected}`\n+    )\n+  }\n+})",
