            "body": "'use strict'\n\nconst test = require('node:test')\nconst Request = require('../lib/request')\n\ntest('.port parses port correctly', (t) => {\n  const fixtures = [\n    {\n      expected: 80,\n      req: {\n        headers: {\n          host: 'example.com:80'\n        }\n      }\n    },\n    {\n      expected: 443,\n      req: {\n        headers: {\n          host: 'example.com:443'\n        }\n      }\n    },\n    {\n      expected: 80,\n      req: {\n        headers: {\n          host: '[::1]:80'\n        }\n      }\n    },\n    {\n      expected: 443,\n      req: {\n        headers: {\n          host: '[::1]:443'\n        }\n      }\n    },\n    {\n      expected: null,\n      req: {\n        headers: {\n          host: '[::1]'\n        }\n      }\n    },\n    {\n      expected: 80,\n      req: {\n        headers: {\n          ':authority': '1.2.3.4:80'\n        }\n      }\n    },\n    {\n      expected: null,\n      req: {\n        headers: {}\n      }\n    }\n  ]\n\n  for (const fixture of fixtures) {\n    const req = new Request(1, {}, fixture.req, '', {}, {})\n    t.assert.equal(\n      req.port,\n      fixture.expected,\n      `${fixture.req.headers.host} should parse to ${fixture.expected}`\n    )\n  }\n})\n",
