          "diff": "diff --git a/packages/client/lib/commands/XAUTOCLAIM.ts b/packages/client/lib/commands/XAUTOCLAIM.ts\n--- a/packages/client/lib/commands/XAUTOCLAIM.ts\n+++ b/packages/client/lib/commands/XAUTOCLAIM.ts\n@@ -1,5 +1,5 @@\n import { RedisCommandArgument, RedisCommandArguments } from '.';\n-import { StreamMessagesReply, transformStreamMessagesReply } from './generic-transformers';\n+import { StreamMessagesNullReply, transformStreamMessagesNullReply } from './generic-transformers';\n \n export const FIRST_KEY_INDEX = 1;\n \n@@ -28,12 +28,12 @@ type XAutoClaimRawReply = [RedisCommandArgument, Array<any>];\n \n interface XAutoClaimReply {\n     nextId: RedisCommandArgument;\n-    messages: StreamMessagesReply;\n+    messages: StreamMessagesNullReply;\n }\n \n export function transformReply(reply: XAutoClaimRawReply): XAutoClaimReply {\n     return {\n         nextId: reply[0],\n-        messages: transformStreamMessagesReply(reply[1])\n+        messages: transformStreamMessagesNullReply(reply[1])\n     };\n }",
          "fullContent": "import { RedisCommandArgument, RedisCommandArguments } from '.';\nimport { StreamMessagesNullReply, transformStreamMessagesNullReply } from './generic-transformers';\n\nexport const FIRST_KEY_INDEX = 1;\n\nexport interface XAutoClaimOptions {\n    COUNT?: number;\n}\n\nexport function transformArguments(\n    key: RedisCommandArgument,\n    group: RedisCommandArgument,\n    consumer: RedisCommandArgument,\n    minIdleTime: number,\n    start: string,\n    options?: XAutoClaimOptions\n): RedisCommandArguments {\n    const args = ['XAUTOCLAIM', key, group, consumer, minIdleTime.toString(), start];\n\n    if (options?.COUNT) {\n        args.push('COUNT', options.COUNT.toString());\n    }\n\n    return args;\n}\n\ntype XAutoClaimRawReply = [RedisCommandArgument, Array<any>];\n\ninterface XAutoClaimReply {\n    nextId: RedisCommandArgument;\n    messages: StreamMessagesNullReply;\n}\n\nexport function transformReply(reply: XAutoClaimRawReply): XAutoClaimReply {\n    return {\n        nextId: reply[0],\n        messages: transformStreamMessagesNullReply(reply[1])\n    };\n}\n",
